!function(n){"use strict";var t=document.getElementById("thanks-root");if(t){n.DP_CONFIG;var e=n.Tracking,i=n.DPCart.money,s=function(n){return String(n).replace(/[&<>"']/g,function(n){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[n]})},a=null;try{a=JSON.parse(sessionStorage.getItem("dp_last_order")||"null")}catch(n){}if(a){if(t.innerHTML='<div class="done__ico"><svg class="ico"><use href="#i-check"/></svg></div><h1>Дякуємо за замовлення!</h1><p>Номер вашого замовлення: <b>'+s(a.id)+"</b>. Менеджер зв'яжеться з вами за номером <b>"+s(a.phoneRaw)+'</b>, щоб підтвердити наявність і узгодити деталі.</p><div class="done__order">'+a.items.map(function(n){return"<div><span>"+s(n.title)+" <small>(арт. "+s(n.sku)+")</small></span><b>"+n.qty+" × "+i(n.price)+"</b></div>"}).join("")+(a.discount?"<div><span>Знижка за акцією</span><b>−"+i(a.discount)+"</b></div>":"")+'<div class="done__total"><span>Разом за товари</span><b>'+i(a.value)+'</b></div></div><p class="hint">Доставка: '+s(a.delivery)+", "+s(a.address)+". Оплата: "+s(a.payment)+". Вартість доставки — за тарифом перевізника.</p>"+(a.test?'<p class="hint hint--warn">⚠ Тестовий режим: форму ще не підключено до скрипта замовлень (orderEndpoint порожній), замовлення нікуди не надіслано.</p>':"")+'<a class="btn btn--primary btn--lg" href="'+DP.url("/novorichni-tovary/")+'">Продовжити покупки</a>',!a.tracked){e.purchase({id:a.id,eventId:a.eventId,value:a.value,discount:a.discount,phone:a.phone,items:a.items}),a.tracked=!0;try{sessionStorage.setItem("dp_last_order",JSON.stringify(a))}catch(n){}}}else t.innerHTML='<p>Ми не знайшли нещодавнього замовлення. Якщо ви щойно оформили його — зв\'яжіться з нами в Telegram, і ми все перевіримо.</p><a class="btn btn--primary" href="'+DP.url("/novorichni-tovary/")+'">До каталогу</a>'}}(window);
